INSERT INTO docs (id, slug, title, content) VALUES
  (1, 'seasonal-vegetable-soup', 'SELECT a Seasonal Vegetable Soup', 'Choose vegetables that are fresh where you live. Sauté onions, add stock, then simmer the selected vegetables until tender. Finish with herbs and lemon.'),
  (2, 'weeknight-pasta', 'SELECT a Weeknight Pasta', 'Select one sturdy pasta shape, one seasonal vegetable, and a salty cheese. Reserve pasta water and union the sauce with the noodles over gentle heat.'),
  (3, 'local-markets', 'WHERE to Find Better Ingredients', 'A good recipe begins with knowing where ingredients are at their best. Compare a farmers market, a neighborhood shop, and your pantry before planning dinner.'),
  (4, 'store-herbs', 'WHERE Fresh Herbs Keep Best', 'Store tender herbs where they stay cool but do not freeze. Wrap basil loosely, keep parsley stems in water, and select only dry leaves for storage.'),
  (5, 'fusion-stew', 'UNION of Two Stew Traditions', 'This stew creates a union of tomato, chickpeas, smoked paprika, and ginger. Add each spice gradually so the shared base remains balanced.'),
  (6, 'grain-salad', 'UNION Grain Salad', 'Union warm grains with crisp vegetables only after the grains have cooled slightly. A sharp dressing keeps the textures distinct.'),
  (7, 'overnight-dough', 'Let the Dough SLEEP Overnight', 'A long cold rest develops flavor with little work. Let the dough sleep in the refrigerator, then bring it back to room temperature before shaping.'),
  (8, 'rested-cookie-dough', 'Why Cookie Dough Should SLEEP', 'Letting cookie dough sleep hydrates the flour and deepens caramel notes. Cover it well so it does not absorb refrigerator aromas.'),
  (9, 'sauces-and-pasta', 'JOIN Pasta with the Right Sauce', 'Join delicate noodles with light sauces and ridged shapes with chunky sauces. The best match helps every bite carry seasoning.'),
  (10, 'bread-and-soup', 'JOIN Bread and Soup', 'Join toasted bread with soup at the last moment for contrast, or simmer it longer when you want a thick rustic texture.'),
  (11, 'meal-prep', 'GROUP BY Your Weekly Meal Prep', 'Group by cooking method: roast vegetables together, simmer one pot of grains, and prepare two sauces. Recombine them into different meals.'),
  (12, 'timing-dinner', 'ORDER BY Cooking Time', 'Order by the longest cooking task first. Start the roast, prepare the sauce, then select quick garnishes while everything finishes.');
